"""Shared desktop palette and controls for every calculation page."""
from PySide6.QtWidgets import QApplication

def workbench_style():
 dark=QApplication.palette().window().color().lightness()<128
 base,panel,text,border,header,alternate=('#1b2432','#253245','#edf2fa','#455670','#34445c','#2b3a50') if dark else ('#f5f7fb','#ffffff','#1e293b','#d5deea','#edf2f8','#f8fafc')
 return f'''QMainWindow,QDialog,QWidget#SupportEditor {{background:{base};}} QLabel,QCheckBox {{color:{text};background:transparent;}} QGroupBox {{background:{panel};color:{text};border:1px solid {border};border-radius:7px;font-weight:600;margin-top:12px;padding:16px 12px 12px;}} QGroupBox::title {{subcontrol-origin:margin;left:12px;}} QLineEdit,QComboBox,QDoubleSpinBox,QSpinBox,QTextEdit {{background:{panel};color:{text};border:1px solid {border};border-radius:4px;min-height:28px;padding:3px 6px;}} QTableWidget {{background:{panel};color:{text};alternate-background-color:{alternate};gridline-color:{border};border:1px solid {border};}} QHeaderView::section {{background:{header};color:{text};padding:8px 6px;font-weight:600;border:0;border-right:1px solid {border};border-bottom:1px solid {border};}} QTabWidget::pane {{border:1px solid {border};background:{panel};}} QTabBar::tab {{background:{base};color:{text};padding:8px 14px;}} QTabBar::tab:selected {{background:{panel};border-bottom:2px solid #2563eb;}} QPushButton {{background:{panel};color:{text};border:1px solid {border};border-radius:4px;min-height:30px;padding:3px 12px;}} QPushButton#Generate {{background:#2563eb;color:white;border:0;min-height:36px;}} QScrollArea {{background:{panel};border:0;}} QWidget[surface="true"] {{background:{panel};}}''' + f"QCheckBox {{spacing:8px;min-height:28px;padding:2px 5px;}} QCheckBox::indicator {{width:20px;height:20px;border:2px solid {border};border-radius:4px;background:{panel};}} QCheckBox::indicator:checked {{background:#2563eb;border:2px solid #93c5fd;image:url(:/qt-project.org/styles/commonstyle/images/standardbutton-apply-16.png);}} QLineEdit:read-only {{background:{header};}} QTableWidget::item:selected {{background:#2563eb;color:white;}}"
